-- Produces testdata/pg_golden.csv: PostgreSQL's results for the operand pairs below.
\set ON_ERROR_STOP on
CREATE TEMP TABLE pairs (id int, a numeric, b numeric);
\copy (SELECT id, a::text, b::text, (a + b)::text AS add, (a - b)::text AS sub, (a * b)::text AS mul, (a / b)::text AS div, sign(a - b) AS cmp, round(a, 2)::text AS round2, trunc(a, 2)::text AS trunc2, CASE WHEN a >= 0 THEN sqrt(a)::text END AS sqrt FROM pairs ORDER BY id) TO 'testdata/pg_golden.csv' WITH (FORMAT csv, HEADER true)
